WITH calendar AS (SELECT d::DATE AS mon FROM generate_series(DATE '2024-01-01',DATE '2024-12-01',INTERVAL '1 month') t(d)),monthly AS (SELECT date_trunc('month',o.ordered_at AT TIME ZONE 'UTC')::DATE AS mon,p.category_id,sum(i.qty::DECIMAL(18,0)*i.unit_price)::DECIMAL(38,2) AS revenue FROM orders o JOIN order_items i USING(order_id) JOIN products p USING(product_id) WHERE o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00' GROUP BY mon,p.category_id),totals AS (SELECT c.mon,coalesce(sum(m.revenue),0)::DECIMAL(38,2) AS revenue FROM calendar c LEFT JOIN monthly m USING(mon) GROUP BY c.mon),lagged AS (SELECT mon,revenue,lag(revenue,1,0) OVER(ORDER BY mon) AS previous_revenue FROM totals) SELECT mon,revenue,previous_revenue,(revenue-previous_revenue)::DECIMAL(38,2) AS change FROM lagged ORDER BY mon;
